fun lexCompare(a: List<Int>, b: List<Int>): Int {
    for (i in 0 until minOf(a.size, b.size)) if (a[i] != b[i]) return a[i].compareTo(b[i])
    return a.size.compareTo(b.size)
}
object Canonical {
    fun dense(values: List<List<Int>>): List<Int> {
        val ranks = values.distinct().sortedWith(Comparator(::lexCompare)).withIndex().associate {
            it.value to it.index + 1
        }
        return values.map {
            ranks.getValue(it)
        }
    }
    fun refine(m: Molecule, input: List<Int>): List<Int> {
        var ranks = input
        while (true) {
            val classes = ranks.toSet().size
            val values = m.atoms.indices.map {
                i ->
                val neighbors = m.neighbors[i].map {
                    Pair(ranks[it.first], m.bonds[it.second].kind)
                }.sortedWith(compareBy<Pair<Int, Int>> {
                    it.first
                }.thenBy {
                    it.second
                })
                listOf(ranks[i]) + neighbors.flatMap {
                    listOf(it.first, it.second)
                }
            }
            ranks = dense(values)
            if (ranks.toSet().size == classes) return ranks
        }
    }
    fun ranks(m: Molecule, elements: Elements): Pair<List<Int>, Int> {
        val values = m.atoms.mapIndexed {
            i, a -> listOf(m.neighbors[i].size, elements.getValue(a.element).number, a.mass, a.charge, a.hydrogens, if (a.aromatic) 1 else 0)
        }
        var ranks = refine(m, dense(values))
        val classes = ranks.toSet().size
        while (ranks.toSet().size < m.atoms.size) {
            val counts = ranks.groupingBy {
                it
            }.eachCount()
            val tied = counts.filterValues {
                it > 1
            }.keys.minOrNull()!!
            val atom = ranks.indexOf(tied)
            val split = ranks.mapIndexed {
                i, rank -> listOf(rank * 2 - if (i == atom) 1 else 0)
            }
            ranks = refine(m, dense(split))
        }
        return Pair(ranks, classes)
    }
    fun atom(m: Molecule, i: Int, elements: Elements): String {
        val a = m.atoms[i]
        val symbol = if (a.aromatic) a.element.lowercase() else a.element
        val allowed = a.element in listOf("B", "C", "N", "O", "P", "S", "F", "Cl", "Br", "I") && (!a.aromatic || a.element in listOf("B", "C", "N", "O", "P", "S"))
        if (allowed && a.mass == 0 && a.charge == 0 && (!a.aromatic || m.needsPi(i, elements, true) == m.needsPi(i, elements, false)) && m.organicHydrogens(i, elements) == a.hydrogens) return symbol
        return buildString {
            append('[')
            if (a.mass != 0) append(a.mass)
            append(symbol)
            if (a.hydrogens > 0) {
                append('H'); if (a.hydrogens > 1) append(a.hydrogens)
            }
            if (a.charge != 0) {
                append(if (a.charge > 0) '+' else '-'); if (kotlin.math.abs(a.charge) > 1) append(kotlin.math.abs(a.charge))
            }
            append(']')
        }
    }
    fun bond(m: Molecule, edge: Int): String {
        val b = m.bonds[edge]
        val aromatic = m.atoms[b.a].aromatic && m.atoms[b.b].aromatic && b.ring
        return when (b.kind) {
            1 -> if (aromatic) "-" else ""; 2 -> "="; 3 -> "#"; else -> if (aromatic) "" else ":"
        }
    }
    fun smiles(m: Molecule, elements: Elements): Pair<String, Int> {
        val (ranks, classes) = this.ranks(m, elements)
        val start = ranks.indexOf(1)
        val visited = IntArray(m.atoms.size)
        val kinds = IntArray(m.bonds.size)
        val children = List(m.atoms.size) {
            mutableListOf<Pair<Int, Int>>()
        }
        val assigned = mutableMapOf<Int, Int>()
        var serial = 0
        fun visit(a: Int, incoming: Int?) {
            visited[a] = ++serial
            for ((b, edge) in m.neighbors[a].sortedBy {
                ranks[it.first]
            }) {
                if (edge == incoming || kinds[edge] == 2) continue
                if (visited[b] == 0) {
                    kinds[edge] = 1; children[a].add(Pair(b, edge)); visit(b, edge)
                }
                else kinds[edge] = 2
            }
        }
        fun write(a: Int): String = buildString {
            append(atom(m, a, elements))
            for ((_, edge) in m.neighbors[a].filter {
                kinds[it.second] == 2
            }.sortedBy {
                visited[it.first]
            }) {
                val old = assigned.remove(edge)
                val number: Int
                if (old != null) number = old
                else {
                    var next = 1
                    while (next in assigned.values) next++
                    number = next; assigned[edge] = next; append(bond(m, edge))
                }
                append(if (number < 10) "$number" else "%${number.toString().padStart(2, '0')}")
            }
            for ((i, child) in children[a].withIndex()) {
                val branch = i + 1 < children[a].size
                if (branch) append('(')
                append(bond(m, child.second)); append(write(child.first))
                if (branch) append(')')
            }
        }
        visit(start, null)
        return Pair(write(start), classes)
    }
}

import java.io.File
import kotlin.math.abs
fun validName(text: String): Boolean = text.length in 1..32 && text.all {
    it in 'A'..'Z' || it in 'a'..'z' || it in '0'..'9' || it in "_-"
}
fun number(text: String, low: Int, high: Int): Int? {
    if (text.isEmpty() || text.length > 1 && text[0] == '0' || !text.all {
        it in '0'..'9'
    }) return null
    return text.toIntOrNull()?.takeIf {
        it in low..high
    }
}
fun threshold(text: String): Ratio? {
    val a = text.split('/')
    if (a.size != 2) return null
    val p = number(a[0], 0, 99) ?: return null
    val q = number(a[1], 1, 99) ?: return null
    return if (p <= q) Ratio(p, q) else null
}
fun analyze(text: String, elements: Elements): Molecule {
    val m = SmilesParser.parse(text, elements).molecule
    RingsAromatic.detect(m)
    for (b in m.bonds) if (b.kind == 0) b.kind = if (m.atoms[b.a].aromatic && m.atoms[b.b].aromatic && b.ring) 4 else 1
    RingsAromatic.kekulize(m, elements)
    for ((i, a) in m.atoms.withIndex()) {
        if (a.bracket) {
            if (m.multiplicity(i) + a.hydrogens > elements.getValue(a.element).valences.last() + abs(a.charge)) throw MoleculeError("bad valence", a.column)
        } else a.hydrogens = m.organicHydrogens(i, elements) ?: throw MoleculeError("bad valence", a.column)
    }
    return m
}
fun scaffold(m: Molecule, elements: Elements): String? {
    if (m.rings.isEmpty()) return null
    val ringAtoms = m.rings.flatten().toSet()
    val remaining = m.atoms.indices.toMutableSet()
    while (true) {
        val removed = remaining.sorted().firstOrNull {
            i -> i !in ringAtoms && m.neighbors[i].count {
                it.first in remaining
            } == 1
        } ?: break
        remaining.remove(removed)
    }
    val core = remaining.toSet()
    for (b in m.bonds) if (b.kind == 2) {
        if (b.a in core) remaining.add(b.b); if (b.b in core) remaining.add(b.a)
    }
    val graph = Molecule()
    val index = mutableMapOf<Int, Int>()
    for (i in remaining.sorted()) {
        index[i] = graph.atoms.size
        val extra = m.neighbors[i].filter {
            it.first !in remaining
        }.sumOf {
            m.bonds[it.second].multiplicity
        }
        graph.atoms.add(m.atoms[i].copy(hydrogens = m.atoms[i].hydrogens + extra))
    }
    for (b in m.bonds) if (b.a in remaining && b.b in remaining) graph.bonds.add(b.copy(a = index.getValue(b.a), b = index.getValue(b.b)))
    graph.rebuild()
    return Canonical.smiles(graph, elements).first
}
data class Analysis(val name: String, val graph: Molecule, val smiles: String, val classes: Int, val formula: String, val weight: Int,
val heavy: Int, val rotatable: Int, val donors: Int, val acceptors: Int, val lipinski: String, val charge: Int,
val scaffold: String?, val fingerprint: Fingerprint)
fun properties(name: String, m: Molecule, elements: Elements): Analysis {
    val counts = mutableMapOf<String, Int>()
    var weight = 0
    var hydrogens = 0
    for (a in m.atoms) {
        counts[a.element] = counts.getOrDefault(a.element, 0) + 1
        hydrogens += a.hydrogens
        weight += if (a.mass == 0) elements.getValue(a.element).mass else a.mass * 1000
    }
    counts["H"] = counts.getOrDefault("H", 0) + hydrogens
    weight += hydrogens * elements.getValue("H").mass
    counts.entries.removeIf {
        it.value == 0
    }
    val order = mutableListOf<String>()
    if ("C" in counts) {
        order.add("C"); if ("H" in counts) order.add("H")
    }
    order.addAll(counts.keys.filter {
        it !in order
    }.sorted())
    val formula = order.joinToString("") {
        it + if (counts.getValue(it) > 1) counts.getValue(it).toString() else ""
    }
    val heavy = m.atoms.count {
        it.element != "H"
    }
    val heavyDegree = m.neighbors.map {
        ns -> ns.count {
            m.atoms[it.first].element != "H"
        }
    }
    val triple = m.neighbors.map {
        ns -> ns.any {
            m.bonds[it.second].multiplicity == 3
        }
    }
    val rotatable = m.bonds.count {
        it.multiplicity == 1 && !it.ring && heavyDegree[it.a] >= 2 && heavyDegree[it.b] >= 2 && !triple[it.a] && !triple[it.b]
    }
    val acceptors = m.atoms.count {
        it.element in listOf("N", "O")
    }
    val donors = m.atoms.indices.count {
        i -> val a = m.atoms[i]; a.element in listOf("N", "O") && (a.hydrogens > 0 || m.neighbors[i].any {
            m.atoms[it.first].element == "H"
        })
    }
    val violations = (if (weight > 500000) 1 else 0) + (if (donors > 5) 1 else 0) + (if (acceptors > 10) 1 else 0)
    val (smiles, classes) = Canonical.smiles(m, elements)
    return Analysis(name, m, smiles, classes, formula, weight, heavy, rotatable, donors, acceptors, if (violations <= 1) "pass" else "fail", m.atoms.sumOf {
        it.charge
    }, scaffold(m, elements), Search.fingerprint(m, elements))
}
data class RingSystem(val rings: List<Int>, val kind: String, val atoms: Int)
fun ringSystems(m: Molecule): List<RingSystem> {
    val remaining = m.rings.indices.toMutableSet()
    val result = mutableListOf<RingSystem>()
    while (remaining.isNotEmpty()) {
        val start = remaining.minOrNull()!!
        val group = mutableSetOf<Int>()
        val stack = mutableListOf(start)
        remaining.remove(start)
        while (stack.isNotEmpty()) {
            val i = stack.removeAt(stack.lastIndex)
            group.add(i)
            val neighbors = remaining.filter {
                j -> m.rings[i].any {
                    it in m.rings[j]
                }
            }.sorted()
            for (j in neighbors) {
                remaining.remove(j); stack.add(j)
            }
        }
        val rings = group.sorted()
        var kind = if (rings.size == 1) "isolated" else "spiro"
        for (x in rings.indices) for (y in x + 1 until rings.size) {
            val common = m.rings[rings[x]].intersect(m.rings[rings[y]].toSet()).toList()
            if (common.size >= 2) {
                if (common.size == 2 && m.bond(common[0], common[1]) != null) {
                    if (kind != "bridged") kind = "fused"
                }
                else kind = "bridged"
            }
        }
        result.add(RingSystem(rings, kind, rings.flatMap {
            m.rings[it]
        }.toSet().size))
    }
    return result
}
fun paragraph(output: MutableList<String>, lines: List<String>) {
    if (output.isNotEmpty()) output.add(""); output.addAll(lines)
}
fun canonicalReport(molecules: List<Analysis>): List<String> {
    val result = mutableListOf<String>()
    paragraph(result, listOf("CANONICAL molecules=${molecules.size} unique=${molecules.map { it.smiles }.toSet().size}") + molecules.map {
        "${it.name} ${it.smiles} classes=${it.classes} charge=${if (it.charge > 0) "+" else ""}${it.charge}"
    })
    fun names(ids: List<Int>): String = ids.joinToString(",") {
        molecules[it].name
    }
    val duplicates = molecules.indices.groupBy {
        molecules[it].smiles
    }.entries.filter {
        it.value.size >= 2
    }.sortedBy {
        it.value[0]
    }
    paragraph(result, listOf("DUPLICATES groups=${duplicates.size} molecules=${duplicates.sumOf { it.value.size }}") + duplicates.mapIndexed {
        i, g -> "group ${i + 1} ${g.key} members=${names(g.value)}"
    })
    val isomers = molecules.indices.groupBy {
        molecules[it].formula
    }.entries.filter {
        g -> g.value.map {
            molecules[it].smiles
        }.toSet().size >= 2
    }.sortedBy {
        it.value[0]
    }
    paragraph(result, listOf("ISOMERS groups=${isomers.size}") + isomers.mapIndexed {
        i, g -> "isomer ${i + 1} ${g.key} forms=${g.value.map { molecules[it].smiles }.toSet().size} members=${names(g.value)}"
    })
    val scaffolds = molecules.indices.filter {
        molecules[it].scaffold != null
    }.groupBy {
        molecules[it].scaffold!!
    }.entries.sortedWith(compareByDescending<Map.Entry<String, List<Int>>> {
        it.value.size
    }.thenBy {
        it.key
    })
    paragraph(result, listOf("SCAFFOLDS distinct=${scaffolds.size} acyclic=${molecules.count { it.scaffold == null }}") + scaffolds.mapIndexed {
        i, g -> "scaffold ${i + 1} ${g.key} count=${g.value.size} members=${names(g.value)}"
    })
    return result
}
fun ringsReport(molecules: List<Analysis>): List<String> {
    val result = mutableListOf<String>()
    var total = 0
    var aromatic = 0
    var cyclic = 0
    val sizes = sortedMapOf<Int, Int>()
    val kinds = listOf("isolated", "fused", "spiro", "bridged")
    val kindCounts = IntArray(4)
    for (m in molecules) if (m.graph.rings.isNotEmpty()) {
        val graph = m.graph
        val aromaticCount = graph.rings.count {
            r -> r.all {
                graph.atoms[it].aromatic
            }
        }
        val systems = ringSystems(graph)
        cyclic++; total += graph.rings.size; aromatic += aromaticCount
        val lines = mutableListOf("MOLECULE ${m.name} atoms=${graph.atoms.size} bonds=${graph.bonds.size} rings=${graph.rings.size} aromatic=$aromaticCount systems=${systems.size} ring_atoms=${graph.rings.flatten().toSet().size} ring_bonds=${graph.bonds.count { it.ring }}")
        for ((i, ring) in graph.rings.withIndex()) {
            sizes[ring.size] = sizes.getOrDefault(ring.size, 0) + 1
            lines.add("ring ${i + 1} size=${ring.size} aromatic=${if (ring.all { graph.atoms[it].aromatic }) "yes" else "no"} hetero=${ring.count { graph.atoms[it].element != "C" }} atoms=${ring.joinToString("-") { (it + 1).toString() }}")
        }
        for ((i, system) in systems.withIndex()) {
            kindCounts[kinds.indexOf(system.kind)]++
            lines.add("system ${i + 1} kind=${system.kind} rings=${system.rings.joinToString(",") { (it + 1).toString() }} atoms=${system.atoms}")
        }
        val doubles = graph.bonds.filter {
            it.kind == 4 && it.multiplicity == 2
        }.map {
            "${it.a + 1}=${it.b + 1}"
        }
        lines.add("kekule " + if (doubles.isEmpty()) "-" else doubles.joinToString(" "))
        paragraph(result, lines)
    }
    val sizeText = if (sizes.isEmpty()) "-" else sizes.entries.joinToString(" ") {
        "${it.key}=${it.value}"
    }
    paragraph(result, listOf("SUMMARY molecules=${molecules.size} cyclic=$cyclic rings=$total aromatic=$aromatic", "sizes $sizeText", "systems isolated=${kindCounts[0]} fused=${kindCounts[1]} spiro=${kindCounts[2]} bridged=${kindCounts[3]}"))
    return result
}
class QueryError(val reason: String) : Exception(reason)
data class Query(val kind: String, val id: String, val args: List<String>, val indices: MutableList<Int> = mutableListOf(),
var pattern: Pattern? = null, var count: Int = 0, var threshold: Ratio = Ratio(0, 1))
fun query(a: List<String>, names: Map<String, Int>, elements: Elements): Query {
    val kind = a[0]
    val args = a.drop(2)
    val valid = if (kind in listOf("MATCH", "CLUSTER")) args.size == 1 else if (kind == "MATRIX") args.size in 2..12 else args.size == 2
    if (!valid) throw QueryError("bad arguments")
    val q = Query(kind, a[1], args)
    fun index(name: String): Int = names[name] ?: throw QueryError("unknown molecule $name")
    when (kind) {
        "MATCH" -> try {
            q.pattern = Pattern.parse(args[0], elements)
        } catch (e: MoleculeError) {
            throw QueryError("bad pattern ${e.reason} at column ${e.column}")
        }
        "CLUSTER" -> q.threshold = threshold(args[0]) ?: throw QueryError("bad threshold")
        "NEAREST", "WITHIN" -> {
            q.indices.add(index(args[0]))
            if (kind == "NEAREST") q.count = number(args[1], 1, 99) ?: throw QueryError("bad count")
            else q.threshold = threshold(args[1]) ?: throw QueryError("bad threshold")
        }
        else -> {
            for (name in args) q.indices.add(index(name))
            if (q.indices.toSet().size != q.indices.size) throw QueryError("repeated molecule")
        }
    }
    return q
}
fun process(q: Query, molecules: List<Analysis>, sub: MutableList<String>, similarity: MutableList<String>, counts: IntArray) {
    fun sim(a: Int, b: Int): Ratio = Search.similarity(molecules[a].fingerprint, molecules[b].fingerprint)
    when (q.kind) {
        "MATCH" -> {
            counts[0]++
            val pattern = q.pattern!!
            val matches = molecules.mapIndexed {
                i, m -> Pair(i, Search.embeddings(pattern, m.graph))
            }.filter {
                it.second.count > 0
            }
            counts[1] += matches.size
            val lines = mutableListOf("MATCH ${q.id} ${q.args[0]} atoms=${pattern.graph.atoms.size} bonds=${pattern.graph.bonds.size} hits=${matches.size} embeddings=${matches.sumOf { it.second.count }}")
            for ((i, match) in matches) lines.add("${molecules[i].name} count=${match.count} unique=${match.unique} map=${match.first.joinToString(",")}")
            val top = matches.maxByOrNull {
                it.second.count
            }
            if (top != null) lines.add("top ${molecules[top.first].name} count=${top.second.count}")
            paragraph(sub, lines)
        }
        "CONTAINS" -> {
            counts[2]++
            val matches = Search.embeddings(Pattern.molecule(molecules[q.indices[0]].graph), molecules[q.indices[1]].graph)
            val result = if (matches.count == 0) "no" else {
                counts[3]++
                "yes count=${matches.count} unique=${matches.unique} map=${matches.first.joinToString(",")}"
            }
            paragraph(sub, listOf("CONTAINS ${q.id} ${q.args[0]} ${q.args[1]} result=$result"))
        }
        "MATRIX" -> {
            val lines = mutableListOf("MATRIX ${q.id} size=${q.indices.size}")
            for (a in q.indices) lines.add("row ${molecules[a].name} " + q.indices.joinToString(" ") {
                sim(a, it).toString()
            })
            var bestA = 0
            var bestB = 1
            var best = sim(q.indices[0], q.indices[1])
            for (a in q.indices.indices) for (b in a + 1 until q.indices.size) {
                val s = sim(q.indices[a], q.indices[b])
                if (s > best) {
                    bestA = a; bestB = b; best = s
                }
            }
            lines.add("best ${q.args[bestA]} ${q.args[bestB]} $best")
            paragraph(similarity, lines)
        }
        "NEAREST", "WITHIN" -> {
            val x = q.indices[0]
            var results = molecules.indices.filter {
                it != x
            }.map {
                Pair(it, sim(x, it))
            }.sortedWith(Comparator {
                a, b ->
                val order = b.second.compareTo(a.second)
                if (order == 0) a.first.compareTo(b.first) else order
            })
            results = if (q.kind == "NEAREST") results.take(q.count) else results.filter {
                it.second >= q.threshold
            }
            val first = if (q.kind == "NEAREST") "NEAREST ${q.id} ${q.args[0]} count=${results.size}" else "WITHIN ${q.id} ${q.args[0]} threshold=${q.threshold} count=${results.size}"
            paragraph(similarity, listOf(first) + results.mapIndexed {
                i, r -> "${i + 1} ${molecules[r.first].name} ${r.second} common=${r.second.p}"
            })
        }
        "COMPARE" -> {
            val a = molecules[q.indices[0]]
            val b = molecules[q.indices[1]]
            val s = Search.similarity(a.fingerprint, b.fingerprint)
            paragraph(similarity, listOf("COMPARE ${q.id} ${q.args[0]} ${q.args[1]} bits=${a.fingerprint.bits.size},${b.fingerprint.bits.size} common=${s.p} union=${s.q} tanimoto=$s identical=${if (a.smiles == b.smiles) "yes" else "no"}"))
        }
        "CLUSTER" -> {
            val neighbors = molecules.indices.map {
                i -> molecules.indices.filter {
                    it != i && sim(i, it) >= q.threshold
                }
            }
            val order = molecules.indices.sortedWith(compareByDescending<Int> {
                neighbors[it].size
            }.thenBy {
                it
            })
            val used = mutableSetOf<Int>()
            val clusters = mutableListOf<List<Int>>()
            for (i in order) if (used.add(i)) {
                val members = mutableListOf(i)
                for (j in neighbors[i]) if (used.add(j)) members.add(j)
                clusters.add(members)
            }
            val lines = mutableListOf("CLUSTER ${q.id} threshold=${q.threshold} clusters=${clusters.size} singletons=${clusters.count { it.size == 1 }}")
            for ((i, cluster) in clusters.filter {
                it.size > 1
            }.withIndex()) lines.add("cluster ${i + 1} centroid=${molecules[cluster[0]].name} size=${cluster.size} members=${cluster.joinToString(",") { molecules[it].name }}")
            paragraph(similarity, lines)
        }
    }
}
fun write(name: String, lines: List<String>) {
    File("output").mkdirs()
    File("output/$name").writeText(if (lines.isEmpty()) "" else lines.joinToString("\n") + "\n")
}
fun main() {
    val elements = readElements()
    val molecules = mutableListOf<Analysis>()
    val seen = mutableSetOf<String>()
    val moleculeErrors = mutableListOf<String>()
    val causes = mutableMapOf<String, Int>()
    var moleculeLines = 0
    fun cause(reason: String) {
        causes[reason] = causes.getOrDefault(reason, 0) + 1
    }
    for ((i, line) in File("input/molecules.smi").readLines().withIndex()) if (line.isNotEmpty() && !line.startsWith('#')) {
        moleculeLines++
        val a = line.split(' ')
        if (a.size != 2 || a[0].isEmpty() || !validName(a[1])) {
            moleculeErrors.add("line ${i + 1}: bad line"); cause("bad line")
        }
        else if (!seen.add(a[1])) {
            moleculeErrors.add("line ${i + 1} ${a[1]}: duplicate name"); cause("duplicate name")
        }
        else try {
            molecules.add(properties(a[1], analyze(a[0], elements), elements))
        }
        catch (e: MoleculeError) {
            moleculeErrors.add("line ${i + 1} ${a[1]}: ${e.reason} at column ${e.column}"); cause(e.reason)
        }
    }
    val names = molecules.withIndex().associate {
        it.value.name to it.index
    }
    val propertyLines = mutableListOf("name,formula,weight,heavy_atoms,rings,rotatable,donors,acceptors,lipinski")
    for (m in molecules) {
        val weight = "${m.weight / 1000}.${(m.weight % 1000).toString().padStart(3, '0')}"
        propertyLines.add("${m.name},${m.formula},$weight,${m.heavy},${m.graph.rings.size},${m.rotatable},${m.donors},${m.acceptors},${m.lipinski}")
    }
    val substructure = mutableListOf<String>()
    val similarity = mutableListOf("FINGERPRINTS molecules=${molecules.size} size=1024 depth=5")
    similarity.addAll(molecules.map {
        "${it.name} bits=${it.fingerprint.bits.size} paths=${it.fingerprint.paths}"
    })
    val identifiers = mutableSetOf<String>()
    val queryErrors = mutableListOf<String>()
    var queryLines = 0
    var queryValid = 0
    val counts = IntArray(4)
    for ((i, line) in File("input/queries.txt").readLines().withIndex()) if (line.isNotEmpty() && !line.startsWith('#')) {
        queryLines++
        val a = line.split(' ')
        if (a[0] !in listOf("MATCH", "CONTAINS", "MATRIX", "NEAREST", "WITHIN", "COMPARE", "CLUSTER")) {
            queryErrors.add("line ${i + 1}: unknown query"); cause("unknown query")
        }
        else if (a.size == 1 || !validName(a[1])) {
            queryErrors.add("line ${i + 1} ${a[0]}: bad id"); cause("bad id")
        }
        else try {
            if (!identifiers.add(a[1])) throw QueryError("duplicate id")
            val q = query(a, names, elements)
            queryValid++
            process(q, molecules, substructure, similarity, counts)
        } catch (e: QueryError) {
            queryErrors.add("line ${i + 1} ${a[0]} ${a[1]}: ${e.reason}")
            cause(if (e.reason.startsWith("bad pattern ")) "bad pattern" else if (e.reason.startsWith("unknown molecule ")) "unknown molecule" else e.reason)
        }
    }
    paragraph(substructure, listOf("SUMMARY patterns=${counts[0]} hits=${counts[1]} contains=${counts[2]} found=${counts[3]}"))
    val errors = mutableListOf<String>()
    paragraph(errors, listOf("MOLECULES lines=$moleculeLines valid=${molecules.size} errors=${moleculeErrors.size}") + moleculeErrors)
    paragraph(errors, listOf("QUERIES lines=$queryLines valid=$queryValid errors=${queryErrors.size}") + queryErrors)
    val sortedCauses = causes.entries.sortedWith(compareByDescending<Map.Entry<String, Int>> {
        it.value
    }.thenBy {
        it.key
    })
    paragraph(errors, listOf("CAUSES kinds=${causes.size}") + sortedCauses.map {
        "${it.key}=${it.value}"
    })
    write("properties.csv", propertyLines)
    write("canonical.txt", canonicalReport(molecules))
    write("rings.txt", ringsReport(molecules))
    write("substructure.txt", substructure)
    write("similarity.txt", similarity)
    write("errors.txt", errors)
}

import java.io.File
data class Element(val number: Int, val mass: Int, val valences: List<Int>)
typealias Elements = Map<String, Element>
fun readElements(): Elements = File("input/elements.txt").readLines().filter {
    it.isNotEmpty() && !it.startsWith('#')
}.associate {
    val a = it.split(' ')
    a[0] to Element(a[1].toInt(), a[2].toInt(), a[3].split(',').map(String::toInt))
}
data class Atom(val element: String, val aromatic: Boolean = false, val mass: Int = 0, val charge: Int = 0,
var hydrogens: Int = 0, val bracket: Boolean = false, val column: Int = 1)
data class Bond(var a: Int, var b: Int, var kind: Int, var multiplicity: Int = 0, var ring: Boolean = false)
class Molecule {
    val atoms = mutableListOf<Atom>()
    val bonds = mutableListOf<Bond>()
    var neighbors: List<List<Pair<Int, Int>>> = emptyList()
    var rings: List<List<Int>> = emptyList()
    fun rebuild() {
        bonds.sortWith(compareBy<Bond> {
            it.a
        }.thenBy {
            it.b
        })
        val adjacency = List(atoms.size) {
            mutableListOf<Pair<Int, Int>>()
        }
        for ((i, bond) in bonds.withIndex()) {
            adjacency[bond.a].add(Pair(bond.b, i))
            adjacency[bond.b].add(Pair(bond.a, i))
        }
        neighbors = adjacency.map {
            it.sortedBy {
                edge -> edge.first
            }
        }
    }
    fun bond(a: Int, b: Int): Int? = neighbors[a].firstOrNull {
        it.first == b
    }?.second
    fun base(i: Int): Int = neighbors[i].sumOf {
        val kind = bonds[it.second].kind; if (kind == 4) 1 else kind
    }
    fun multiplicity(i: Int): Int = neighbors[i].sumOf {
        bonds[it.second].multiplicity
    }
    fun needsPi(i: Int, elements: Elements, hydrogens: Boolean): Boolean {
        val atom = atoms[i]
        return atom.aromatic && elements.getValue(atom.element).valences[0] + atom.charge >= base(i) + (if (hydrogens) atom.hydrogens else 0) + 1
    }
    fun organicHydrogens(i: Int, elements: Elements): Int? {
        val total = multiplicity(i)
        return elements.getValue(atoms[i].element).valences.firstOrNull {
            it >= total
        }?.minus(total)
    }
}
class MoleculeError(val reason: String, val column: Int) : Exception(reason)

object RingsAromatic {
    fun edgeSet(m: Molecule, ring: List<Int>): Set<Int> = ring.indices.map {
        m.bond(ring[it], ring[(it + 1) % ring.size])!!
    }.toSet()
    fun detect(m: Molecule) {
        val n = m.atoms.size
        val candidates = mutableListOf<Pair<List<Int>, Set<Int>>>()
        val seen = mutableSetOf<Set<Int>>()
        for (root in 0 until n) {
            val parent = IntArray(n) {
                -1
            }
            val visited = BooleanArray(n)
            val queue = ArrayDeque<Int>()
            visited[root] = true
            queue.addLast(root)
            while (queue.isNotEmpty()) {
                val a = queue.removeFirst()
                for ((b, _) in m.neighbors[a]) if (!visited[b]) {
                    visited[b] = true; parent[b] = a; queue.addLast(b)
                }
            }
            fun path(atom: Int): List<Int> {
                val result = mutableListOf(atom)
                var x = atom
                while (parent[x] >= 0) {
                    x = parent[x]; result.add(x)
                }
                return result
            }
            for (bond in m.bonds) {
                if (parent[bond.a] == bond.b || parent[bond.b] == bond.a) continue
                val a = path(bond.a)
                val b = path(bond.b)
                if (a.any {
                    it != root && it in b
                }) continue
                val ring = a.reversed() + b.dropLast(1)
                val edges = edgeSet(m, ring)
                if (seen.add(edges)) candidates.add(Pair(ring, edges))
            }
        }
        val basis = mutableMapOf<Int, Set<Int>>()
        val selected = mutableListOf<List<Int>>()
        for ((ring, edges) in candidates.sortedBy {
            it.first.size
        }) {
            var vector = edges
            while (vector.isNotEmpty()) {
                val pivot = vector.maxOrNull()!!
                val b = basis[pivot]
                if (b == null) {
                    basis[pivot] = vector; selected.add(ring); break
                }
                vector = (vector - b) + (b - vector)
            }
        }
        m.rings = selected.map {
            r ->
            val k = r.indexOf(r.minOrNull()!!)
            val rotated = r.drop(k) + r.take(k)
            if (rotated[1] < rotated.last()) rotated else listOf(rotated[0]) + rotated.drop(1).reversed()
        }.sortedWith(Comparator {
            a, b -> if (a.size != b.size) a.size.compareTo(b.size) else lexCompare(a, b)
        })
        for (ring in m.rings) for (edge in edgeSet(m, ring)) m.bonds[edge].ring = true
    }
    fun kekulize(m: Molecule, elements: Elements) {
        val remaining = m.atoms.indices.filter {
            m.needsPi(it, elements, true)
        }.toMutableSet()
        val paired = mutableMapOf<Int, Int>()
        fun matching(system: Set<Int>): Boolean {
            val u = system.filter {
                it !in paired
            }.minOrNull() ?: return true
            for ((v, edge) in m.neighbors[u]) if (v in system && v !in paired && m.bonds[edge].kind == 4) {
                paired[u] = v; paired[v] = u
                if (matching(system)) return true
                paired.remove(u); paired.remove(v)
            }
            return false
        }
        while (remaining.isNotEmpty()) {
            val start = remaining.minOrNull()!!
            val system = mutableSetOf<Int>()
            val stack = mutableListOf(start)
            remaining.remove(start)
            while (stack.isNotEmpty()) {
                val a = stack.removeAt(stack.lastIndex)
                system.add(a)
                for ((b, edge) in m.neighbors[a]) if (m.bonds[edge].kind == 4 && remaining.remove(b)) stack.add(b)
            }
            if (!matching(system)) throw MoleculeError("kekulization failed", m.atoms[system.minOrNull()!!].column)
        }
        for (bond in m.bonds) bond.multiplicity = if (bond.kind == 4) (if (paired[bond.a] == bond.b) 2 else 1) else bond.kind
    }
}

sealed interface Matcher {
    data object AnyAtom : Matcher
    data object Aliphatic : Matcher
    data object Aromatic : Matcher
    data class AtomList(val atoms: List<Pair<String, Boolean>>) : Matcher
}
data class Pattern(val graph: Molecule, val atoms: List<Matcher>) {
    companion object {
        fun parse(text: String, elements: Elements): Pattern {
            val parsed = SmilesParser.parse(text, elements, true)
            return Pattern(parsed.molecule, parsed.matchers)
        }
        fun molecule(m: Molecule): Pattern = Pattern(m, m.atoms.map {
            Matcher.AtomList(listOf(Pair(it.element, it.aromatic)))
        })
    }
}
data class Matches(val count: Int, val unique: Int, val first: List<Int>)
data class Fingerprint(val bits: MutableSet<Int> = mutableSetOf(), var paths: Int = 0)
data class Ratio(val p: Int, val q: Int) : Comparable<Ratio> {
    override fun compareTo(other: Ratio): Int = (p * other.q).compareTo(other.p * q)
    override fun toString(): String {
        var a = p
        var b = q
        while (b != 0) {
            val r = a % b; a = b; b = r
        }
        return "${p / a}/${q / a}"
    }
}
object Search {
    fun patternAtom(s: String, column: Int): Pair<Matcher, Int> = when (s[0]) {
        '*' -> Pair(Matcher.AnyAtom, 1)
        'A' -> Pair(Matcher.Aliphatic, 1)
        'a' -> Pair(Matcher.Aromatic, 1)
        '[' -> {
            val end = s.indexOf(']')
            if (end < 0) throw MoleculeError("unclosed bracket", column)
            val atoms = s.substring(1, end).split(',').map {
                val (element, aromatic, n) = SmilesParser.organic(it) ?: throw MoleculeError("bad bracket atom", column)
                if (n != it.length) throw MoleculeError("bad bracket atom", column)
                Pair(element, aromatic)
            }
            Pair(Matcher.AtomList(atoms), end + 1)
        }
        else -> {
            val (element, aromatic, n) = SmilesParser.organic(s) ?: throw MoleculeError("unexpected character", column)
            Pair(Matcher.AtomList(listOf(Pair(element, aromatic))), n)
        }
    }
    fun embeddings(pattern: Pattern, m: Molecule): Matches {
        val map = mutableListOf<Int>()
        val used = BooleanArray(m.atoms.size)
        val sets = mutableSetOf<List<Int>>()
        var count = 0
        var first = emptyList<Int>()
        fun visit() {
            val a = map.size
            if (a == pattern.atoms.size) {
                count++
                if (first.isEmpty()) first = map.map {
                    it + 1
                }
                sets.add(map.sorted())
                return
            }
            for (b in m.atoms.indices) if (!used[b]) {
                val atom = m.atoms[b]
                val matches = when (val matcher = pattern.atoms[a]) {
                    Matcher.AnyAtom -> true
                    Matcher.Aliphatic -> !atom.aromatic
                    Matcher.Aromatic -> atom.aromatic
                    is Matcher.AtomList -> Pair(atom.element, atom.aromatic) in matcher.atoms
                }
                if (!matches) continue
                val bonds = pattern.graph.neighbors[a].filter {
                    it.first < a
                }.all {
                    (v, edge) ->
                    val f = m.bond(b, map[v])
                    if (f == null) false else when (val kind = pattern.graph.bonds[edge].kind) {
                        0 -> m.bonds[f].kind in listOf(1, 4); 5 -> true; else -> m.bonds[f].kind == kind
                    }
                }
                if (bonds) {
                    used[b] = true; map.add(b); visit(); map.removeAt(map.lastIndex); used[b] = false
                }
            }
        }
        visit()
        return Matches(count, sets.size, first)
    }
    fun fingerprint(m: Molecule, elements: Elements): Fingerprint {
        val codes = m.atoms.mapIndexed {
            i, a -> 16 * elements.getValue(a.element).number + (if (a.aromatic) 8 else 0) + m.neighbors[i].size
        }
        val result = Fingerprint()
        val path = mutableListOf<Int>()
        fun walk(hash: Int) {
            result.paths++
            result.bits.add(hash % 1024)
            if (path.size == 6) return
            for ((b, edge) in m.neighbors[path.last()]) if (b !in path) {
                val h = ((hash * 31 + m.bonds[edge].kind) % 1000003 * 31 + codes[b]) % 1000003
                path.add(b); walk(h); path.removeAt(path.lastIndex)
            }
        }
        for (i in m.atoms.indices) {
            path.clear(); path.add(i); walk(codes[i])
        }
        return result
    }
    fun similarity(a: Fingerprint, b: Fingerprint): Ratio {
        val common = a.bits.intersect(b.bits).size
        return Ratio(common, a.bits.size + b.bits.size - common)
    }
}

data class Parsed(val molecule: Molecule, val matchers: List<Matcher>)
data class OpenRing(val atom: Int, val symbol: Pair<Int, Int>?, val column: Int)
object SmilesParser {
    fun organic(text: String): Triple<String, Boolean, Int>? {
        if (text.startsWith("Cl")) return Triple("Cl", false, 2)
        if (text.startsWith("Br")) return Triple("Br", false, 2)
        val c = text.firstOrNull() ?: return null
        if (c in "BCNOPSFI") return Triple(c.toString(), false, 1)
        if (c in "bcnops") return Triple(c.uppercaseChar().toString(), true, 1)
        return null
    }
    fun atom(text: String, column: Int, elements: Elements): Pair<Atom, Int> {
        if (text[0] != '[') {
            val (element, aromatic, n) = organic(text) ?: throw MoleculeError("unexpected character", column)
            return Pair(Atom(element, aromatic, column = column), n)
        }
        val end = text.indexOf(']')
        if (end < 0) throw MoleculeError("unclosed bracket", column)
        val s = text.substring(1, end)
        var i = 0
        while (i < s.length && s[i] in '0'..'9') i++
        if (i >= 4 || i > 0 && s[0] == '0') throw MoleculeError("bad bracket atom", column)
        val mass = if (i == 0) 0 else s.substring(0, i).toInt()
        if (i == s.length) throw MoleculeError("bad bracket atom", column)
        val element: String
        val aromatic: Boolean
        if (s[i] in "bcnops") {
            element = s[i].uppercaseChar().toString(); aromatic = true; i++
        }
        else if (s[i] in 'A'..'Z') {
            val one = s[i].toString()
            if (i + 1 < s.length && s[i + 1] in 'a'..'z' && s.substring(i, i + 2) in elements) {
                element = s.substring(i, i + 2); i += 2
            } else if (one in elements) {
                element = one; i++
            }
            else throw MoleculeError("unknown element", column)
            aromatic = false
        } else throw MoleculeError("bad bracket atom", column)
        if (i < s.length && s[i] == '@') {
            i++; if (i < s.length && s[i] == '@') i++
        }
        var hydrogens = 0
        if (i < s.length && s[i] == 'H') {
            hydrogens = 1; i++
            if (i < s.length && s[i] in '0'..'9') {
                hydrogens = s[i] - '0'; i++
            }
        }
        var charge = 0
        if (i < s.length && s[i] in "+-") {
            val sign = if (s[i] == '+') 1 else -1
            i++
            var amount = 1
            if (i < s.length && s[i] in '1'..'9') {
                amount = s[i] - '0'; i++
            }
            charge = sign * amount
        }
        if (i != s.length) throw MoleculeError("bad bracket atom", column)
        return Pair(Atom(element, aromatic, mass, charge, hydrogens, true, column), end + 1)
    }
    fun symbol(c: Char, pattern: Boolean): Int? = when (c) {
        '-' -> 1
        '=' -> 2
        '#' -> 3
        ':' -> 4
        '~' -> if (pattern) 5 else null
        '/', '\\' -> if (pattern) null else 1
        else -> null
    }
    fun parse(text: String, elements: Elements, pattern: Boolean = false): Parsed {
        val molecule = Molecule()
        val matchers = mutableListOf<Matcher>()
        var current: Int? = null
        var pending: Pair<Int, Int>? = null
        val branches = mutableListOf<Pair<Int, Int>>()
        val rings = mutableMapOf<Int, OpenRing>()
        var i = 0
        fun add(a: Int, b: Int, kind: Int) {
            molecule.bonds.add(Bond(minOf(a, b), maxOf(a, b), kind))
        }
        while (i < text.length) {
            val c = text[i]
            val column = i + 1
            val kind = symbol(c, pattern)
            if (kind != null) {
                if (current == null || pending != null) throw MoleculeError("misplaced bond", column)
                pending = Pair(kind, column); i++
            } else if (c == '(') {
                if (current == null || pending != null || i > 0 && text[i - 1] == '(') throw MoleculeError("misplaced branch", column)
                branches.add(Pair(current!!, column)); i++
            } else if (c == ')') {
                if (branches.isEmpty()) throw MoleculeError("unmatched parenthesis", column)
                pending?.let {
                    throw MoleculeError("dangling bond", it.second)
                }
                if (i > 0 && text[i - 1] == '(') throw MoleculeError("empty branch", column)
                current = branches.removeAt(branches.lastIndex).first; i++
            } else if (c in '0'..'9' || c == '%') {
                val atom = current ?: throw MoleculeError("misplaced ring closure", column)
                val number: Int
                if (c == '%') {
                    if (i + 2 >= text.length || text[i + 1] !in '0'..'9' || text[i + 2] !in '0'..'9') throw MoleculeError("bad ring number", column)
                    number = text.substring(i + 1, i + 3).toInt(); i += 3
                } else {
                    number = c - '0'; i++
                }
                val closing = pending
                pending = null
                val opening = rings.remove(number)
                if (opening != null) {
                    if (opening.atom == atom) throw MoleculeError("self bond", column)
                    if (opening.symbol != null && closing != null && opening.symbol.first != closing.first) throw MoleculeError("ring bond mismatch", column)
                    if (molecule.bonds.any {
                        it.a == minOf(opening.atom, atom) && it.b == maxOf(opening.atom, atom)
                    }) throw MoleculeError("duplicate bond", column)
                    add(opening.atom, atom, (closing ?: opening.symbol)?.first ?: 0)
                } else rings[number] = OpenRing(atom, closing, column)
            } else {
                val atom: Atom
                val length: Int
                if (pattern) {
                    val (matcher, n) = Search.patternAtom(text.substring(i), column)
                    matchers.add(matcher); atom = Atom("", column = column); length = n
                } else {
                    val parsed = this.atom(text.substring(i), column, elements)
                    atom = parsed.first; length = parsed.second
                }
                val next = molecule.atoms.size
                molecule.atoms.add(atom)
                current?.let {
                    add(it, next, pending?.first ?: 0)
                }
                current = next; pending = null; i += length
            }
        }
        pending?.let {
            throw MoleculeError("dangling bond", it.second)
        }
        branches.firstOrNull()?.let {
            throw MoleculeError("unmatched parenthesis", it.second)
        }
        rings.values.minByOrNull {
            it.column
        }?.let {
            throw MoleculeError("unclosed ring", it.column)
        }
        molecule.rebuild()
        return Parsed(molecule, matchers)
    }
}
